<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import PagedList from './PagedList.vue'
import { assignmentState, type AssignmentSummary } from '../assessments'
import { stamp } from '../timetable'
const props=defineProps<{request:(path:string,options?:RequestInit)=>Promise<unknown>;role:string;courses:{id:string;title:string}[];revision:number;courseFocus:string;opening:boolean}>()
const emit=defineEmits<{open:[item:AssignmentSummary];create:[];late:[];assistant:[]}>()
const course=ref(props.courseFocus), keyword=ref(''), applied=ref(''), view=ref(props.role==='student'?'todo':'active'), counts=ref<Record<string,number>>({}), refresh=ref(0)
const tabs=computed(()=>props.role==='student'?[['todo','待完成'],['late','补交事项'],['submitted','已提交'],['all','全部']]:[['active','进行中'],['grading','待批改'],['draft','草稿'],['ended','已结束'],['all','全部']])
const scope=computed(()=>JSON.stringify([course.value,applied.value,view.value,refresh.value]))
const items=computed<AssignmentSummary[]>(()=>{void props.revision;return []})
const controller=new AbortController()
let sequence=0
async function load(page:number,pageSize:number) {
  const current=++sequence
  const params=new URLSearchParams({page:String(page),page_size:String(pageSize),task_view:view.value,keyword:applied.value})
  if(course.value)params.set('course_id',course.value)
  const result=await props.request(`/api/v1/assignments/directory?${params}`,{signal:controller.signal}) as {items:AssignmentSummary[];total:number;page:number;page_size:number;counts:Record<string,number>}
  if(current===sequence)counts.value=result.counts
  return result
}
watch(()=>props.courseFocus,value=>{course.value=value})
const action=(item:AssignmentSummary)=>props.role!=='student'?(item.status==='draft'?'核对并发布':item.ungraded_count?'进入批改':'管理作业'):item.submitted?(item.submission_status==='graded'?'查看反馈':'查看提交'):assignmentState(item)==='已截止'||item.status==='closed'||item.late_request_status==='pending'?'查看补交安排':'继续作答'
const deadline=(item:AssignmentSummary)=>item.late_request_status==='approved'&&item.late_approved_until?`补交至 ${stamp(item.late_approved_until)}`:item.due_at?`${stamp(item.due_at)} 截止`:'未设置截止时间'
onBeforeUnmount(()=>controller.abort())
</script>
<template>
  <section class="assignment-directory" :aria-label="role==='student'?'我的作业查询':'作业管理查询'">
    <header class="task-directory-heading"><div><p>{{ role==='student'?'从待办继续，专注完成每一份作业。':'按教学流程管理作业，从待办直接进入批改。' }}</p></div><div v-if="role!=='student'" class="task-directory-actions"><button type="button" @click="emit('late')">补交审批</button><button type="button" @click="emit('assistant')">✦ AI 辅助备题</button><button type="button" class="primary" @click="emit('create')">＋ 创建作业</button></div></header>
    <form class="task-directory-filters" @submit.prevent="applied=keyword.trim();refresh++"><label>课程<select v-model="course"><option value="">全部课程</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><label class="task-search">查找作业<input v-model="keyword" type="search" maxlength="100" placeholder="作业名称或课程名称" /></label><button type="submit">查询</button><button type="button" @click="keyword='';applied='';course='';refresh++">重置</button></form>
    <nav class="task-directory-tabs" aria-label="作业状态"><button v-for="[key,label] in tabs" :key="key" type="button" :aria-pressed="view===key" @click="view=key"><span>{{ label }}</span><b v-if="counts[key]!==undefined">{{ counts[key] }}</b></button></nav>
    <PagedList :items="items" :scope="scope" :load-page="load" label="作业任务" state-key="assignment-directory" v-slot="{items:rows,loading,error}">
      <div class="task-list-head"><span>课程与作业</span><span>截止与进展</span><span>操作</span></div>
      <button v-for="item in rows" :key="item.id" type="button" class="task-directory-row" :disabled="opening" @click="emit('open',item)"><span class="task-row-main"><small>{{ item.course_title }}</small><strong>{{ item.title }}</strong><span>{{ item.question_count }} 道题 <template v-if="role!=='student'"> · {{ item.submission_count }} 人提交 <b v-if="item.ungraded_count"> · {{ item.ungraded_count }} 份待批改</b></template></span></span><span class="task-row-progress"><span class="task-status" :class="{done:item.submission_status==='graded',late:['已截止','补交申请中'].includes(assignmentState(item))}">{{ assignmentState(item) }}<template v-if="role==='student'&&item.submission_status==='graded'"> · {{ item.score }}/{{ item.max_score }}</template></span><small>{{ deadline(item) }}</small></span><span class="task-row-action">{{ opening?'正在打开…':action(item) }} <i>›</i></span></button>
      <div v-if="!rows.length&&!loading&&!error" class="task-directory-empty"><span aria-hidden="true">✓</span><h3>{{ role==='student'&&view==='todo'?'当前没有待完成作业':'暂无符合条件的作业' }}</h3><p>{{ role==='student'?'可以切换状态查看提交记录，或前往练习中心继续学习。':'可以调整筛选条件，或创建一份新作业。' }}</p><button v-if="view!=='all'" type="button" @click="view='all'">查看全部作业</button></div>
    </PagedList>
  </section>
</template>
<style scoped>
.assignment-directory{background:white;border:1px solid #e1e8f3;border-radius:18px;padding:24px;color:#2c4666;min-width:0}.task-directory-heading{display:flex;gap:16px;align-items:center;justify-content:space-between;margin-bottom:22px}.task-directory-heading p{font-size:13px;color:#7288a2;margin:0;line-height:1.8}.task-directory-actions{display:flex;gap:8px;flex-wrap:wrap}button{font-size:12px;border-radius:10px;padding:10px 14px;background:#edf3fc;color:#486d9b;border:1px solid #dae5f3}.primary{background:#356fc5;color:white;border-color:#356fc5}.task-directory-filters{display:flex;gap:12px;align-items:end;padding:16px;background:#f7f9fd;border-radius:12px}.task-directory-filters label{display:grid;gap:7px;font-size:11px;color:#7a8fa9;min-width:0}.task-directory-filters select,.task-directory-filters input{padding:11px 13px;border:1px solid #dce5f1;border-radius:10px;background:white;color:#2d496c;font-size:13px;min-width:0;width:100%;box-sizing:border-box}.task-directory-filters label:first-child{flex:1}.task-search{flex:1.5}.task-directory-tabs{display:flex;gap:8px;overflow:auto;margin:22px 0 8px;padding-bottom:8px}.task-directory-tabs button{display:flex;gap:10px;align-items:center;white-space:nowrap;background:transparent;border-color:transparent}.task-directory-tabs button[aria-pressed=true]{background:#eaf1ff;border-color:#c7d9f5;color:#2b65b3}.task-directory-tabs b{font-size:10px;border-radius:5px;background:#e5ebf5;padding:3px 6px;color:#6e86a6}.task-list-head,.task-directory-row{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(160px,1fr) 100px;gap:18px;align-items:center}.task-list-head{font-size:11px;color:#8b9cb2;padding:14px 10px;border-bottom:1px solid #e8edf5}.task-directory-row{width:100%;text-align:left;border:0;border-bottom:1px solid #e9eef6;border-radius:0;background:white;color:#2f4969;padding:22px 10px}.task-directory-row:hover{background:#f8faff}.task-row-main{display:grid;gap:9px;min-width:0}.task-row-main small{font-size:11px;color:#8194ad;font-weight:400}.task-row-main strong{font-size:14px;line-height:1.7;overflow-wrap:anywhere}.task-row-main>span{font-size:11px;color:#8094ae;font-weight:400}.task-row-main b{font-weight:500;color:#b3803f}.task-row-progress{display:grid;gap:10px;justify-items:start}.task-row-progress small{font-size:11px;color:#8396ad;font-weight:400;line-height:1.7}.task-status{font-size:11px;border-radius:6px;padding:5px 8px;background:#edf3fd;color:#527cad}.task-status.done{background:#ebf7f0;color:#448663}.task-status.late{background:#fff3e7;color:#aa783e}.task-row-action{font-size:12px;color:#3b70b8;text-align:right}.task-row-action i{font-style:normal;margin-left:7px}.task-directory-empty{text-align:center;padding:42px 12px}.task-directory-empty>span{background:#eef5ff;color:#7098d0;display:inline-grid;place-items:center;width:45px;height:45px;border-radius:14px;font-size:22px}.task-directory-empty h3{font-size:16px;margin-top:18px}.task-directory-empty p{font-size:12px;color:#8798ad;line-height:1.9}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #afc9ee;outline-offset:2px}
@media(max-width:1000px){.task-directory-heading{align-items:start;flex-direction:column}.task-list-head,.task-directory-row{grid-template-columns:minmax(0,1.5fr) minmax(130px,1fr) 90px}}
@media(max-width:650px){.assignment-directory{padding:16px;border-radius:14px}.task-directory-filters{display:grid;grid-template-columns:1fr 1fr;padding:12px;gap:10px}.task-directory-filters label{grid-column:1/-1}.task-directory-filters input,.task-directory-filters select{font-size:16px}.task-directory-tabs{gap:3px;margin:16px 0 0}.task-directory-tabs button{padding:9px 10px;gap:6px;font-size:12px}.task-list-head{display:none}.task-directory-row{grid-template-columns:1fr auto;gap:12px;padding:20px 0}.task-row-main{grid-column:1/-1;gap:7px}.task-row-main strong{font-size:14px}.task-row-progress small{font-size:10px}.task-row-action{font-size:11px}.task-directory-actions button{font-size:11px;padding:9px 10px}.task-directory-empty{padding:30px 0}}
</style>
